INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24701, 'Luke 21:2', 'Luke', 21, 2, '&nbsp;او هغۀ يوه غريبه کونډه وليدله چې دوه د تانبې سيکې يې ورواچولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24702, 'Luke 21:3', 'Luke', 21, 3, '&nbsp;هغۀ وفرمائيل، ”زۀ تاسو ته رښتيا وايم چې دې غريبې کونډې د دې نورو ټولو نه زياتې واچولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24703, 'Luke 21:4', 'Luke', 21, 4, '&nbsp;ځکه چې دې نورو چې په شکرانې کښې څۀ هم واچول هغوئ د مال د زياتوالى په سبب واچول خو د هغې سره چې د خپلې ګزارې نه هم کم وُو، هغه ټولې يې واچولې“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24704, 'Luke 21:5', 'Luke', 21, 5, '&nbsp;ځينې خلقو د خُدائ د کور او د هغې د ښکلو کاڼو او په ورکړے شوو نذرانو چې ښائسته کړے شوى وُو، د هغۀ په حقله خبرې کولې. عيسىٰ ورته وفرمائيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24705, 'Luke 21:6', 'Luke', 21, 6, '&nbsp;”دا څيزونه چې تاسو وينئ، داسې وخت راتلونکے دے چې په دې کښې به يو کاڼے هم د بل دپاسه پاتې نۀ شى او ټول به ونړولے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24706, 'Luke 21:7', 'Luke', 21, 7, '&nbsp;هغوئ عيسىٰ نه تپوس وکړو چې، ”اُستاذه، دا هر څۀ به کله پېښيږى؟ او د دې د رانزدې کېدو نښې به څۀ وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24707, 'Luke 21:8', 'Luke', 21, 8, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”خيال کوئ چې څوک مو بې‌لارې نۀ کړى ځکه چې ډېر به زما په نوم راشى او دعوىٰ به کوى او وائى به چې زۀ عيسىٰ يم، او وخت نزدې راغلے دے خو هغۀ پسې مۀ ځئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24708, 'Luke 21:9', 'Luke', 21, 9, '&nbsp;او کله چې تاسو د جنګونو او الې ګولې خبر واورئ نو مۀ وار خطا کېږئ ځکه چې دا څيزونه به ضرور اول کيږى خو لا به آخر وخت نۀ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24709, 'Luke 21:10', 'Luke', 21, 10, '&nbsp;بيا هغۀ دا وفرمائيل، ”قومونه به د قومونو په خلاف وى، بادشاهۍ به د بادشاهۍ مخالفت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24710, 'Luke 21:11', 'Luke', 21, 11, '&nbsp;لوئې لوئې زلزلې او قحطونه، وباګانې به ځائ په ځائ راځى او په آسمان کښې به هيبتناکې او لوئې نښې ښکاره کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24711, 'Luke 21:12', 'Luke', 21, 12, '&nbsp;خو د دې هر څۀ کېدو نه مخکښې به هغوئ تاسو ونيسى او تاسو به وزوروى. تاسو به عبادتخانو ته حواله کېږئ او بندى‌خانو ته به اچولے کېږئ. تاسو به د بادشاهانو او حاکمانو په وړاندې زما د نوم په سبب راوستلے شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24712, 'Luke 21:13', 'Luke', 21, 13, '&nbsp;نو دا به ستاسو دپاره د ګواهۍ موقع وګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24713, 'Luke 21:14', 'Luke', 21, 14, '&nbsp;خو ياد ساتئ چې د مخکښې نه د خپلې صفائى په حقله د جواب ورکولو فکر مۀ کوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24714, 'Luke 21:15', 'Luke', 21, 15, '&nbsp;ځکه چې زۀ به په خپله تاسو ته د وينا داسې طاقت او حِکمت درکړم چې ستاسو يو مخالف به هم د دې جوګه نۀ وى چې ستاسو د خبرو مقابله وکړى يا يې دروغ ثابت کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24715, 'Luke 21:16', 'Luke', 21, 16, '&nbsp;تر دې چې ستاسو مور پلار، وروڼه، ستاسو خاندان او دوستان به هم تاسو حواله کړى، په تاسو کښې به ځينې مړۀ کړے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24716, 'Luke 21:17', 'Luke', 21, 17, '&nbsp;او زما د نوم په وجه به ټول ستاسو نه نفرت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24717, 'Luke 21:18', 'Luke', 21, 18, '&nbsp;خو ستاسو د سر يو وېښتۀ قدرې به هم ضائع نۀ شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24718, 'Luke 21:19', 'Luke', 21, 19, '&nbsp;د خپل صبر په وجه به تاسو ژوندون وګټئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24719, 'Luke 21:20', 'Luke', 21, 20, '&nbsp;خو کله چې تاسو دا ووينئ چې د يروشلم نه فوجونه راچاپېر شوى دى نو تاسو پوهه شئ چې د هغې بربادى رانزدې شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24720, 'Luke 21:21', 'Luke', 21, 21, '&nbsp;نو بيا هغه څوک چې په يهوديه کښې دى، غرونو ته دې وتښتى. او څوک چې په ښار کښې وى، هغوئ دې د ښار نه بهر وځى او څوک چې د ښار نه بهر په کلو کښې وى هغوئ دې ښار ته نۀ ځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24721, 'Luke 21:22', 'Luke', 21, 22, '&nbsp;ځکه چې په هم دې وخت کښې به خُدائ پاک خپل بدل اخلى او څۀ چې ليکلے شوى دى، هغه ټول به پوره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24722, 'Luke 21:23', 'Luke', 21, 23, '&nbsp;افسوس دے په هغه ښځو چې په دغه وخت کښې اُميدوارې وى او په هغوئ چې بچو له سينه ورکوى. ځکه چې په زمکه به ډېر لوئ مصيبت شروع وى او په دې خلقو به لوئ غضب نازل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24723, 'Luke 21:24', 'Luke', 21, 24, '&nbsp;هغوئ به په تُوره هلاک کړے شى او ټولو مُلکونو ته به لکه د قېديانو بوتلے شى او تر هغه وخت پورې به يروشلم د غېر‌يهوديانو تر پښو لاندې وى ترڅو چې د غېرو قومونو زمانه پوره شوې نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24724, 'Luke 21:25', 'Luke', 21, 25, '&nbsp;په نمر، سپوږمۍ او په ستورو کښې به خاص نښې ښکاره شى. د سمندر د شور او چپو نه به په زمکه ټول قومونه پرېشانه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24725, 'Luke 21:26', 'Luke', 21, 26, '&nbsp;په خلقو کښې به په زمکه د پېښېدونکو واقعاتو د يرې له کبله ساه پاتې نۀ وى ځکه چې آسمانى طاقتونه به لړزولے شوى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24726, 'Luke 21:27', 'Luke', 21, 27, '&nbsp;بيا به هغوئ دا ووينى چې اِبن آدم به په وريځو کښې په ډېر شان او شوکت سره راروان وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24727, 'Luke 21:28', 'Luke', 21, 28, '&nbsp;کله چې دا هر څۀ پېښېدل شروع شى نو پاڅئ او بره وګورئ ځکه چې ستاسو خلاصون نزدې دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24728, 'Luke 21:29', 'Luke', 21, 29, '&nbsp;بيا عيسىٰ هغوئ ته دا مِثال تير کړو چې، ”د اينځر ونې ته وګورئ يا ټولو ونو ته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24729, 'Luke 21:30', 'Luke', 21, 30, '&nbsp;کله چې دا غوټۍ وسپړى نو تاسو به په خپله وينئ او پوهه به شئ چې اوړے رانزدې شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24730, 'Luke 21:31', 'Luke', 21, 31, '&nbsp;هم دغه شان چې تاسو دا هر څۀ په کېدو ووينئ نو پوهه شئ چې د خُدائ پاک بادشاهى نزدې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24731, 'Luke 21:32', 'Luke', 21, 32, '&nbsp;زۀ تاسو ته رښتيا وايم چې دا موجوده پيړۍ به تر هغې ختمه نۀ شى ترڅو چې دا ټولې خبرې ونۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24732, 'Luke 21:33', 'Luke', 21, 33, '&nbsp;زمکه او آسمان به فنا شى خو زما کلام به هيچرې فنا نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24733, 'Luke 21:34', 'Luke', 21, 34, '&nbsp;خيال ساتئ او پام کوئ. خپل زړونه په بد مستۍ، نشو او په دُنياوى غمونو مۀ آخته کوئ، ځکه چې هغه ورځ ناګهانه تاسو لکه د لټ راګېر نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24734, 'Luke 21:35', 'Luke', 21, 35, '&nbsp;ځکه چې هغه ورځ په هر چا راتلونکى ده څوک چې په دې دُنيا کښې اوسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24735, 'Luke 21:36', 'Luke', 21, 36, '&nbsp;خو هر وخت بېدار اوسئ او دا دُعا غواړئ چې تاسو د دې پېښو په وخت کښې دومره تکړه يئ چې خپل ځان بچ کولے شئ او چې د اِبن آدم په وړاندې د ودرېدو جوګه شئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24736, 'Luke 21:37', 'Luke', 21, 37, '&nbsp;عيسىٰ دا ورځې د خُدائ په کور کښې په تعليم ورکولو تېرولې او بيا به هغه د شپې تېرولو دپاره د زيتُونو غرۀ ته تلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24737, 'Luke 21:38', 'Luke', 21, 38, '&nbsp;او سحر وختى به ټول خلق د خُدائ کور ته راټولېدل چې د هغۀ خبرې واورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24738, 'Luke 22:1', 'Luke', 22, 1, '&nbsp;خو اوس د پتيرې روټۍ د اختر ورځ رانزدې شوې وه کومې ته چې د فسح اختر وئيلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24739, 'Luke 22:2', 'Luke', 22, 2, '&nbsp;نو په دې موقع مشرانو اِمامانو او د شرعې عالمانو دا کوشش کولو چې څۀ داسې بهانه ولټوى چې عيسىٰ قتل کړى، ځکه چې هغوئ د خلقو نه يرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24740, 'Luke 22:3', 'Luke', 22, 3, '&nbsp;خو بيا شېطان په يهوداه اِسکريوتى کښې ورننوتو چې په هغه دولسو مريدانو کښې يو وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24741, 'Luke 22:4', 'Luke', 22, 4, '&nbsp;او يهوداه د مشرانو اِمامانو او د خُدائ د کور د آفسرانو سره مشورې له لاړو چې داسې څۀ بهانه پېدا کړى چې عيسىٰ به څنګه هغوئ ته حواله کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24742, 'Luke 22:5', 'Luke', 22, 5, '&nbsp;هغوئ ډېر خوشحاله شول او د هغۀ سره يې د پېسو وعده وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24743, 'Luke 22:6', 'Luke', 22, 6, '&nbsp;نو هغه په دې کار رضا شو او بيا د داسې موقعې په تلاش کښې شو چې کله هغۀ سره نور خلق نۀ وى نو هغوئ ته به يې حواله کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24744, 'Luke 22:7', 'Luke', 22, 7, '&nbsp;بيا د پتيرې روټۍ ورځ راغله په کومه ورځ چې د فسح ګډورے قربانى کېدونکے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24745, 'Luke 22:8', 'Luke', 22, 8, '&nbsp;نو عيسىٰ بيا پطروس او يوحنا د دې هداياتو سره ولېږل چې، ”لاړ شئ او زمونږ دپاره د فسح خوراک تيار کړئ چې وې خورو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24746, 'Luke 22:9', 'Luke', 22, 9, '&nbsp;هغوئ تپوس وکړو چې، ”ستا کوم ځائ خوښ دے چې مونږ په کښې تا له د فسح خوراک تيار کړُو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24747, 'Luke 22:10', 'Luke', 22, 10, '&nbsp;هغۀ جواب ورکړو چې، ”څنګه چې تاسو ښار ته ننوځئ نو تاسو به يو سړے ووينئ چې د اوبو منګے به وړى. هغه چې کوم کور ته ورننوځى نو هم هغه کور ته ورننوځئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24748, 'Luke 22:11', 'Luke', 22, 11, '&nbsp;او د کور خاوند ته دا پېغام ورکړئ، اُستاذ وائى چې هغه د مېلمنو کمره کومه يوه ده چرته چې به زۀ د مريدانو سره د فسح خوراک کوم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24749, 'Luke 22:12', 'Luke', 22, 12, '&nbsp;نو هغه به تاسو ته يوه لويه تياره کړے شوې بالاخانه وښائى، زمونږ دپاره هلته د فسح تيارى وکړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24750, 'Luke 22:13', 'Luke', 22, 13, '&nbsp;هغوئ لاړل او هلته يې هر څيز د هغۀ د وينا په مطابق وليدلو. هغوئ د فسح دپاره تيارے وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24751, 'Luke 22:14', 'Luke', 22, 14, '&nbsp;کله چې هغه وخت راورسېدو نو عيسىٰ سره د خپلو رسولانو روټۍ ته کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24752, 'Luke 22:15', 'Luke', 22, 15, '&nbsp;هغۀ هغوئ ته وفرمائيل چې، ”زما دا ډېر ارمان وو چې د مصيبت زغملو نه وړاندې زۀ تاسو سره د فسح خوراک وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24753, 'Luke 22:16', 'Luke', 22, 16, '&nbsp;ځکه چې زۀ تاسو ته دا وايم چې د دې نه پس به زۀ تر هغې بيا دا روټۍ هيچرې ونۀ خورم ترڅو چې د خُدائ پاک په بادشاهۍ کښې د دې مقصد پوره نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
